import { TimeoutInterruption } from './interruptions.js';
export class ScheduledTimeout {
    static at(date, options) {
        const delay = date.getTime() - Date.now();
        return new ScheduledTimeout({
            delay,
            ...options
        });
    }
    static in(delay, options) {
        return new ScheduledTimeout({
            delay,
            ...options
        });
    }
    #controller;
    #timeout;
    constructor(params){
        const { delay, ...options } = params;
        this.#controller = new AbortController();
        this.#timeout = setTimeout(()=>{
            this.#controller.abort(new TimeoutInterruption({
                message: `Timeout after ${delay}ms`,
                ...options
            }));
        }, delay);
    }
    [Symbol.dispose]() {
        this.cancel();
    }
    get signal() {
        return this.#controller.signal;
    }
    cancel() {
        clearTimeout(this.#timeout);
    }
}
